package org.jlinalg.cli;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class GemmaWorkflowTest {
    @TempDir Path temporary;
    record Result(int code,String out,String err){ }
    Result call(String... args){var out=new ByteArrayOutputStream();var err=new ByteArrayOutputStream();var all=new ArrayList<>(List.of("gemma-tools"));all.addAll(List.of(args));int code=JLinAlgCli.run(all.toArray(String[]::new),new PrintStream(out,true,StandardCharsets.UTF_8),new PrintStream(err,true,StandardCharsets.UTF_8));return new Result(code,out.toString(StandardCharsets.UTF_8),err.toString(StandardCharsets.UTF_8));}
    @Test void helpAndProfilesExposeExactScopeAndRequiredActions(){var r=call("--help");assertEquals(0,r.code());for(String s:List.of("0.98.1","0.98.3","0.98.5","Native","--request","--verify","SKIP3","FAIL2","Required action:","Cell Ranger"))assertTrue(r.out().contains(s),s);var p=call("--profiles");assertEquals(0,p.code());assertTrue(p.out().contains("\"P176_literal_0_983_resolved\":false"));assertTrue(p.out().contains("\"optimizer_convergence_certified\":false"));}
    @Test void setupExportIsExactAndNeverOverwrites()throws Exception{Path target=temporary.resolve("setup");assertEquals(0,call("--export-runtime-setup",target.toString()).code());for(String name:GemmaRuntime.RESOURCES)assertArrayEquals(GemmaRuntime.resource(name),Files.readAllBytes(target.resolve(name)));byte[] original=Files.readAllBytes(target.resolve("export.json"));assertEquals(2,call("--export-runtime-setup",target.toString()).code());assertArrayEquals(original,Files.readAllBytes(target.resolve("export.json")));assertFalse(Files.exists(target.resolve("FAILURE.txt")));assertFalse(Files.exists(target.resolve("COMPLETED.json")));assertTrue(Files.readString(target.resolve("README.txt")).contains("--allow-install"));}
    @Test void unsupportedModesAndUnresolvedLiteralVersionNeverGetSubstituted()throws Exception{var r=request();assertTrue(GemmaRequest.parse(r,false).nativeEngine());r.put("edition","0.983");assertThrows(GemmaRuntime.Unavailable.class,()->GemmaRequest.parse(r,false));r.put("edition","0.98.5");r.put("mode","lmm4");assertThrows(GemmaRuntime.Unavailable.class,()->GemmaRequest.parse(r,false));r.put("mode","gk2");r.put("author_setting",true);assertThrows(IOException.class,()->GemmaRequest.parse(r,false));}
    @Test void invalidArgumentsAndMissingResultsNeverFallThrough(){for(String[] args:List.of(new String[]{"--profiles","x"},new String[]{"--request"},new String[]{"--request","a","--request","b"},new String[]{"--inspect-runtime","a"})){assertEquals(2,call(args).code());}var r=call("--verify",temporary.resolve("missing").toString());assertEquals(2,r.code());assertTrue(r.err().contains("FAIL2 NO COMPLETE RESULT"));}
    @Test void impossibleCapacitiesAndImplicitProcessSettingsAreRejected()throws Exception{var r=request();r.put("process",process());assertThrows(IOException.class,()->GemmaRequest.parse(r,false));r.put("process",null);var c=new LinkedHashMap<String,Object>(capacity());c.put("samples",2.5);r.put("capacity",c);assertThrows(IOException.class,()->GemmaRequest.parse(r,false));r.put("capacity",capacity());var q=new LinkedHashMap<String,Object>(qc());q.put("minimum_frequency",-1);r.put("qc",q);assertThrows(IOException.class,()->GemmaRequest.parse(r,false));}
    @Test void brokenOutputCannotReportSuccessfulHelp()throws Exception{try(var stream=new PrintStream(new OutputStream(){public void write(int b)throws IOException{throw new IOException("controlled unavailable output");}})){assertEquals(2,GemmaToolsCli.run(new String[]{"--help"},stream,stream));}}
    @Test void associationHeadersMatchAllTwelveOriginalEditionModeSchemas()throws Exception{
        try(var in=getClass().getResourceAsStream("/org/jlinalg/genetics/gemma/association-schemas.json")){
            assertNotNull(in);var golden=NextflowFiles.object(SimpleJson.parse(new String(in.readAllBytes(),StandardCharsets.UTF_8)));var headers=NextflowFiles.object(golden.get("headers"));
            for(String edition:List.of("0.98.1","0.98.3","0.98.5"))for(String mode:List.of("lmm1","lmm2","lmm3","lmm4")){
                var r=request();r.put("edition",edition);r.put("engine","original");r.put("mode",mode);r.put("kinship","/declared/matrix.txt");r.put("kinship_ids","/declared/ids.tsv");r.put("optimizer","source-defaults-1e-5-1e5-10-regions");r.put("process",process());var spec=GemmaRequest.parse(r,false);assertEquals(NextflowFiles.object(headers.get(edition)).get(mode),GemmaBundle.associationHeader(spec));
                if(mode.equals("lmm3"))assertEquals(edition.equals("0.98.5")?"absent":"original_uncomputed_zero_placeholder",GemmaBundle.likelihoodKind(spec));
            }
        }
    }
    @Test void inputIdentityIsExactAndNumericMinusNineRemainsObserved()throws Exception{Path root=inputs();var spec=GemmaRequest.parse(request(),false);try(var input=GemmaInputs.read(root,spec,()->{})){assertEquals(32,input.screened.qcSamples());assertEquals(24,input.screened.predictorsUsed());assertEquals(-9,input.phenotype[0]);}Path ids=root.resolve("inputs/sample-ids.tsv");Files.writeString(ids,Files.readString(ids).replace("S000","s000"));assertThrows(IOException.class,()->GemmaInputs.read(root,spec,()->{}));}
    @Test void constantAssociationPhenotypeIsRejectedBeforeUpstreamExecution()throws Exception{Path root=inputs();Files.writeString(root.resolve("inputs/phenotype.txt"),"1\n".repeat(32));var r=request();r.put("engine","original");r.put("mode","lmm4");r.put("kinship","/declared/matrix.txt");r.put("kinship_ids","/declared/ids.tsv");r.put("optimizer","source-defaults-1e-5-1e5-10-regions");r.put("process",process());var spec=GemmaRequest.parse(r,false);var e=assertThrows(IOException.class,()->GemmaInputs.read(root,spec,()->{}));assertTrue(e.getMessage().contains("Constant complete-case phenotype"));}
    @Test void traitExplainedExactlyByCovariatesIsRejectedBeforeUpstreamExecution()throws Exception{
        Path root=inputs();var trait=new StringBuilder();var cov=new StringBuilder();for(int i=0;i<32;i++){trait.append(i).append('\n');cov.append("1 ").append(i).append('\n');}Files.writeString(root.resolve("inputs/phenotype.txt"),trait);Files.writeString(root.resolve("inputs/covariates.txt"),cov);var r=associationRequest();r.put("covariates","/declared/covariates.txt");var spec=GemmaRequest.parse(r,false);var e=assertThrows(IOException.class,()->GemmaInputs.read(root,spec,()->{}));assertTrue(e.getMessage().contains("variation after covariate projection"));
    }
    @Test void workCapacityCoversScreeningAndMatrixValidationTogether()throws Exception{
        Path root=inputs();var r=associationRequest();var c=new LinkedHashMap<String,Object>(capacity());c.put("multiply_adds",60000);r.put("capacity",c);var spec=GemmaRequest.parse(r,false);var e=assertThrows(IOException.class,()->GemmaInputs.read(root,spec,()->{}));assertTrue(e.getMessage().contains("capacity"));
    }
    private Path inputs()throws Exception{Path root=temporary.resolve("capture");Files.createDirectory(root);Files.createDirectory(root.resolve("inputs"));for(String suffix:List.of("bed","bim","fam")){try(var in=getClass().getResourceAsStream("/org/jlinalg/genetics/gemma/baseline/data."+suffix)){assertNotNull(in);Files.copy(in,root.resolve("inputs/data."+suffix));}}var ids=new StringBuilder();var y=new StringBuilder();int i=0;for(String line:Files.readAllLines(root.resolve("inputs/data.fam"))){var f=line.split("\\s+");ids.append(f[0]).append('\t').append(f[1]).append('\n');y.append(i++==0?"-9":f[5]).append('\n');}Files.writeString(root.resolve("inputs/sample-ids.tsv"),ids);Files.writeString(root.resolve("inputs/phenotype.txt"),y);return root;}
    static Map<String,Object> request(){var r=new LinkedHashMap<String,Object>();r.putAll(Map.of("schema_version",1,"edition","0.98.5","engine","native","mode","gk2","genome_build","synthetic","bed_prefix","/declared/data","sample_ids","/declared/ids.tsv","phenotype","/declared/phenotype.txt"));for(String name:List.of("covariates","kinship","kinship_ids","optimizer","process"))r.put(name,null);r.put("qc",qc());r.put("capacity",capacity());return r;}
    static Map<String,Object> associationRequest(){var r=request();r.put("engine","original");r.put("mode","lmm4");r.put("kinship","/declared/matrix.txt");r.put("kinship_ids","/declared/ids.tsv");r.put("optimizer","source-defaults-1e-5-1e5-10-regions");r.put("process",process());return r;}
    static Map<String,Object> qc(){return Map.of("minimum_frequency",.01,"maximum_missingness",.05,"minimum_hwe",0,"maximum_covariate_fraction",.9999);}
    static Map<String,Object> capacity(){return Map.of("samples",100,"variants",100,"input_bytes",67108864,"output_bytes",67108864,"numeric_bytes",10485760,"multiply_adds",100000000L,"native_wall_millis",120000);}
    static Map<String,Object> process(){var p=new LinkedHashMap<String,Object>(Map.of("wall_millis",60000,"address_space_bytes",4294967296L,"cpu_seconds",60,"file_bytes",67108864,"open_files",256,"workspace_bytes",201326592,"file_count",1000,"processes",8,"threads",128,"sampled_rss_bytes",1073741824));p.put("monitor_millis",100);return p;}
}
